from pathlib import Path
import py_compile,shutil
ROOT=Path.cwd()
PKG=ROOT/'qseries_v2/oracle_strategy_intelligence/solana_money/mriya_python_paper_arb'
for n in ('core.py','scanner.py','crosslisted.py','hotpath.py'):
    p=PKG/n
    if not p.is_file(): raise SystemExit('[FAIL] missing prior arb engine dependency: '+str(p.relative_to(ROOT)))
BACK=ROOT/'runtime_state/qseries/qsb038g_backup';BACK.mkdir(parents=True,exist_ok=True)
for n in ('exactpool.py','runtime_exactpool.py'):
    p=PKG/n
    if p.exists():shutil.copy2(p,BACK/n)
(PKG/'exactpool.py').write_text('from __future__ import annotations\nimport json,os,time\nfrom pathlib import Path\nfrom . import core\nfrom . import scanner as prior\nfrom . import crosslisted as cross\nfrom . import hotpath as hot\n\nCOIN_API="https://frontend-api-v3.pump.fun/coins-v2"\nMIN_NET_BPS=15.0\nMAX_SLOT_SPREAD=2\n\ndef coin_state(token,http=core.http_json):\n    j=http(f"{COIN_API}/{token}")\n    if not isinstance(j,dict):raise RuntimeError("PUMP_COIN_STATE_NOT_OBJECT")\n    return j\n\ndef verify_exact_pump_pool(pair,http=core.http_json):\n    token=pair["token"];expected=str(pair["pump_pool"])\n    c=coin_state(token,http)\n    actual=str(c.get("pump_swap_pool") or "")\n    complete=bool(c.get("complete"))\n    if not complete:raise RuntimeError("PUMP_TOKEN_NOT_GRADUATED")\n    if not actual:raise RuntimeError("PUMP_CANONICAL_POOL_MISSING")\n    if actual!=expected:\n        raise RuntimeError("PUMP_POOL_MISMATCH discovered=%s canonical=%s"%(expected,actual))\n    return {"token":token,"discovered_pool":expected,"canonical_pool":actual,\n            "complete":complete,"verified":True}\n\ndef exact_api_quote(pair,input_mint,output_mint,raw_in,http=core.http_json):\n    binding=verify_exact_pump_pool(pair,http)\n    body={"inputMint":input_mint,"outputMint":output_mint,"amount":str(int(raw_in)),\n          "user":core.WALLET,"feePayer":core.WALLET,"slippagePct":0,\n          "frontRunningProtection":False,"tipAmount":0,"encoding":"base64"}\n    j=http(core.PUMP_SWAP_API,"POST",body,20)\n    if not isinstance(j,dict):raise RuntimeError("PUMP_SWAP_RESPONSE_NOT_OBJECT")\n    info=j.get("pumpMintInfo")\n    if not isinstance(info,dict):raise RuntimeError("PUMP_SWAP_NO_MINT_INFO")\n    out=info.get("expectedOutAmount")\n    if out is None:raise RuntimeError("PUMP_SWAP_NO_EXPECTED_OUT")\n    raw=int(out)\n    if raw<=0:raise RuntimeError("PUMP_SWAP_NONPOSITIVE_OUT")\n    tx=j.get("transaction")\n    return {"raw_in":int(raw_in),"raw_out":raw,"binding":binding,\n            "transaction_present":bool(tx),"transaction_b64":tx if isinstance(tx,str) else None,\n            "pump_mint_info":info}\n\ndef direction_a(rpc_url,state,pair,size,http=core.http_json,rpc_fn=core.rpc):\n    meta=pair["meteora"]\n    slot0=rpc_fn(rpc_url,"getSlot",[{"commitment":"processed"}])\n    mq=prior.meteora_from_state(state,meta,core.WSOL,size)\n    if mq["out_mint"]!=pair["token"]:raise RuntimeError("METEORA_A_WRONG_OUTPUT")\n    pq=exact_api_quote(pair,pair["token"],core.WSOL,mq["raw_out"],http)\n    slot1=rpc_fn(rpc_url,"getSlot",[{"commitment":"processed"}])\n    return {"direction":"METEORA_TO_PUMP","token":pair["token"],"pool":meta["address"],\n            "pump_pool":pair["pump_pool"],"start_sol":float(size),"end_sol":pq["raw_out"]/1e9,\n            "slot_start":int(slot0),"slot_end":int(slot1),"pump_binding":pq["binding"],\n            "pump_transaction_present":pq["transaction_present"]}\n\ndef direction_b(rpc_url,state,pair,size,http=core.http_json,rpc_fn=core.rpc):\n    meta=pair["meteora"]\n    slot0=rpc_fn(rpc_url,"getSlot",[{"commitment":"processed"}])\n    raw_sol=int(round(float(size)*1e9))\n    pq=exact_api_quote(pair,core.WSOL,pair["token"],raw_sol,http)\n    tokdec=int(meta["decimals_y"] if meta["token_y"]==pair["token"] else meta["decimals_x"])\n    token_ui=pq["raw_out"]/(10**tokdec)\n    mq=prior.meteora_from_state(state,meta,pair["token"],token_ui)\n    if mq["out_mint"]!=core.WSOL:raise RuntimeError("METEORA_B_WRONG_OUTPUT")\n    slot1=rpc_fn(rpc_url,"getSlot",[{"commitment":"processed"}])\n    return {"direction":"PUMP_TO_METEORA","token":pair["token"],"pool":meta["address"],\n            "pump_pool":pair["pump_pool"],"start_sol":float(size),"end_sol":mq["raw_out"]/1e9,\n            "slot_start":int(slot0),"slot_end":int(slot1),"pump_binding":pq["binding"],\n            "pump_transaction_present":pq["transaction_present"]}\n\ndef finalize(row,fee):\n    start=row["start_sol"];end=row["end_sol"];cost=fee["estimated_total_fee_sol"]\n    net=end-start-cost;bps=net/start*10000.0\n    spread=abs(row["slot_end"]-row["slot_start"])\n    row=dict(row);row.update({"estimated_fee_sol":cost,"net_sol":net,"net_bps":bps,\n                              "slot_spread":spread,"fresh":spread<=MAX_SLOT_SPREAD,\n                              "pre_sim_candidate":bool(spread<=MAX_SLOT_SPREAD and bps>=MIN_NET_BPS)})\n    return row\n\ndef sizes_around(seed=None):\n    base=[.01,.02,.03,.05,.08,.12,.20,.35,.50,.75,1.0]\n    if seed:\n        s=float(seed)\n        base += [s*.65,s*.8,s*.9,s*.95,s,s*1.05,s*1.1,s*1.2,s*1.4]\n    return sorted({round(max(.005,min(2.0,x)),6) for x in base})\n\ndef optimize_pair(root,pair,http=core.http_json,rpc_fn=core.rpc):\n    rpc_url=os.getenv("SOLANA_RPC_URL",core.DEFAULT_RPC)\n    binding=verify_exact_pump_pool(pair,http)\n    state=prior.pool_state(rpc_url,pair["meteora"])\n    fee=hot.fee_model(root,rpc_url,pair,rpc_fn)\n    rows=[];errors=[]\n    for size in sizes_around():\n        for fn in (direction_a,direction_b):\n            try:rows.append(finalize(fn(rpc_url,state,pair,size,http,rpc_fn),fee))\n            except Exception as e:\n                errors.append({"size":size,"direction":fn.__name__,"error":f"{type(e).__name__}: {e}"})\n    if rows:\n        seed=max(rows,key=lambda z:z["net_sol"])["start_sol"]\n        for size in sizes_around(seed):\n            if any(abs(r["start_sol"]-size)<1e-12 for r in rows):continue\n            for fn in (direction_a,direction_b):\n                try:rows.append(finalize(fn(rpc_url,state,pair,size,http,rpc_fn),fee))\n                except Exception as e:errors.append({"size":size,"direction":fn.__name__,"error":f"{type(e).__name__}: {e}"})\n    best=max(rows,key=lambda z:z["net_sol"]) if rows else None\n    return best,rows,errors,fee,binding\n\ndef run(root,http=core.http_json,rpc_fn=core.rpc):\n    _,pairs=cross.crosslisted(root,http,capture_seconds=5,max_intersections=8)\n    print("[CROSSLIST] exact_pairs=%d"%len(pairs),flush=True)\n    allrows=[];allerr=[];best=None\n    for i,pair in enumerate(pairs,1):\n        print("[PAIR %d/%d] token=%s discovered_pump=%s meteora=%s"%(\n          i,len(pairs),pair["token"],pair["pump_pool"],pair["meteora"]["address"]),flush=True)\n        try:b,rows,errs,fee,binding=optimize_pair(root,pair,http,rpc_fn)\n        except Exception as e:\n            print("[PAIR_REJECT] %s: %s"%(type(e).__name__,e),flush=True);continue\n        print("[PUMP_BINDING] discovered=%s canonical=%s verified=%s"%(\n          binding["discovered_pool"],binding["canonical_pool"],binding["verified"]),flush=True)\n        allrows.extend(rows);allerr.extend(errs)\n        if errs:\n            counts={}\n            for e in errs:counts[e["error"]]=counts.get(e["error"],0)+1\n            for msg,n in sorted(counts.items(),key=lambda z:-z[1])[:4]:\n                print("[QUOTE_ERROR] count=%d %s"%(n,msg),flush=True)\n        if b:\n            print("[PAIR_BEST] dir=%s size=%.6f end=%.9f fee=%.9f net=%+.9f bps=%+.2f spread=%d tx_present=%s PRE_SIM_CANDIDATE=%s"%(\n              b["direction"],b["start_sol"],b["end_sol"],b["estimated_fee_sol"],\n              b["net_sol"],b["net_bps"],b["slot_spread"],b["pump_transaction_present"],\n              "YES" if b["pre_sim_candidate"] else "NO"),flush=True)\n            if best is None or b["net_sol"]>best["net_sol"]:best=b\n    out={"revision":"QSB_038G","pairs":pairs,"quotes":allrows,"errors":allerr,"best":best,\n         "execution_authority":False,"truth":"EXACT_CANONICAL_PUMP_POOL_BOUND_PRE_SIM"}\n    p=Path(root)/"runtime_state/qseries/qsb038g_exact_pool/report.json"\n    p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(out,indent=2),encoding="utf-8")\n    return out\n',encoding='utf-8')
(PKG/'runtime_exactpool.py').write_text('from pathlib import Path\nfrom .core import ensure_meteora_math\nfrom .exactpool import run\ndef main():\n    print("[QSB-038G] EXACT PUMPSWAP POOL-BOUND ARB ENGINE",flush=True)\n    print("[FIX] discovered Pump pool must equal pump.fun canonical pump_swap_pool before quote",flush=True)\n    print("[ERRORS] quote failures are printed, never silently converted to BEST NONE",flush=True)\n    print("[MODE] PAPER_ONLY=True execution_authority=FALSE",flush=True)\n    d=ensure_meteora_math();print("[PYTHON_QUOTE_MATH]",d,flush=True)\n    if not d.get("ok"):return\n    r=run(Path.cwd());b=r.get("best")\n    if b:\n        print("[BEST] token=%s dir=%s pump=%s meteora=%s size=%.6f end=%.9f net=%+.9f bps=%+.2f spread=%d PRE_SIM_CANDIDATE=%s"%(\n          b["token"],b["direction"],b["pump_pool"],b["pool"],b["start_sol"],b["end_sol"],\n          b["net_sol"],b["net_bps"],b["slot_spread"],"YES" if b["pre_sim_candidate"] else "NO"),flush=True)\n    else:print("[BEST] NONE -- inspect PAIR_REJECT / QUOTE_ERROR above",flush=True)\nif __name__=="__main__":main()\n',encoding='utf-8')
(ROOT/'test_qsb_038g_exact_pump_pool_binding.py').write_text('import unittest\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.mriya_python_paper_arb import core\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.mriya_python_paper_arb import exactpool as e\n\nPAIR={"token":"TOK","pump_pool":"POOL123","meteora":{"address":"MET","token_x":core.WSOL,"token_y":"TOK","decimals_x":9,"decimals_y":6}}\n\nclass T(unittest.TestCase):\n    def test_exact_pool_match_required(self):\n        def h(url,*a,**k):return {"complete":True,"pump_swap_pool":"POOL123"}\n        x=e.verify_exact_pump_pool(PAIR,h);self.assertTrue(x["verified"])\n        print("[PASS] exact discovered Pump pool must match canonical coin-state pool")\n\n    def test_pool_mismatch_rejected(self):\n        def h(url,*a,**k):return {"complete":True,"pump_swap_pool":"OTHER"}\n        with self.assertRaisesRegex(RuntimeError,"PUMP_POOL_MISMATCH"):e.verify_exact_pump_pool(PAIR,h)\n        print("[PASS] generic mint route cannot silently substitute another Pump pool")\n\n    def test_ungraduated_rejected(self):\n        def h(url,*a,**k):return {"complete":False,"pump_swap_pool":"POOL123"}\n        with self.assertRaisesRegex(RuntimeError,"NOT_GRADUATED"):e.verify_exact_pump_pool(PAIR,h)\n        print("[PASS] bonding-curve token cannot masquerade as PumpSwap AMM pair")\n\n    def test_api_quote_keeps_transaction_evidence(self):\n        calls=[]\n        def h(url,method="GET",body=None,timeout=15):\n            calls.append((url,method,body))\n            if "coins-v2" in url:return {"complete":True,"pump_swap_pool":"POOL123"}\n            return {"transaction":"BASE64TX","pumpMintInfo":{"expectedOutAmount":"123456"}}\n        q=e.exact_api_quote(PAIR,"TOK",core.WSOL,999,h)\n        self.assertEqual(q["raw_out"],123456);self.assertTrue(q["transaction_present"])\n        self.assertEqual(calls[-1][2]["inputMint"],"TOK")\n        print("[PASS] exact-bound Pump quote preserves returned transaction for later simulation")\n\n    def test_fee_and_fresh_gate(self):\n        r={"start_sol":.03,"end_sol":.03012649,"slot_start":10,"slot_end":11}\n        x=e.finalize(r,{"estimated_total_fee_sol":.000005})\n        self.assertTrue(x["pre_sim_candidate"]);self.assertGreater(x["net_bps"],15)\n        print("[PASS] dynamic fee + <=2-slot positive edge produces pre-sim candidate")\n\n    def test_stale_rejected(self):\n        r={"start_sol":.03,"end_sol":.031,"slot_start":10,"slot_end":13}\n        x=e.finalize(r,{"estimated_total_fee_sol":.000005})\n        self.assertFalse(x["pre_sim_candidate"])\n        print("[PASS] stale profitable quote rejected")\n\nif __name__=="__main__":unittest.main(verbosity=2)\n',encoding='utf-8')
(ROOT/'run_qsb_038g_exact_pump_pool_binding.py').write_text("from qseries_v2.oracle_strategy_intelligence.solana_money.mriya_python_paper_arb.runtime_exactpool import main\nif __name__=='__main__':main()\n",encoding='utf-8')
for p in (PKG/'exactpool.py',PKG/'runtime_exactpool.py',ROOT/'test_qsb_038g_exact_pump_pool_binding.py',ROOT/'run_qsb_038g_exact_pump_pool_binding.py'):py_compile.compile(str(p),doraise=True)
print('[PASS] QSB-038G exact PumpSwap pool binding installed into existing arb engine')
print('[BIND] discovered live Pump pool must equal canonical pump_swap_pool for token')
